/**
 * Pull relay for `/v0/deployment-events`.
 *
 * A {@link RelayAdapter} over {@link CursorRelayCore} — the same engine the
 * GitHub SCM and Slack relays use, so registration heartbeats, durable
 * offsets, backoff, and bounded dispatch retry are inherited rather than
 * reimplemented. Only the subscribe/poll paths, the registration body, and
 * the per-event filter differ.
 */
import { CursorRelayCore } from "./cursor-relay-core.js";
import { isRecord } from "./is-record.js";
const DEFAULT_EVENTS = ["deployment.succeeded"];
function deploymentSubscriptionStatuses(json) {
    if (!isRecord(json) || !Array.isArray(json.deploySourceUris)) {
        return [];
    }
    const statuses = [];
    for (const item of json.deploySourceUris) {
        if (!isRecord(item) ||
            typeof item.deploySourceUri !== "string" ||
            typeof item.isSubscribed !== "boolean") {
            continue;
        }
        const status = {
            deploySourceUri: item.deploySourceUri,
            isSubscribed: item.isSubscribed,
        };
        if (typeof item.detail === "string") {
            status.detail = item.detail;
        }
        statuses.push(status);
    }
    return statuses;
}
/** Current subscriptions: a live getter, otherwise the snapshot. */
export function currentDeploymentSubscriptions(subscriptions) {
    return typeof subscriptions === "function" ? subscriptions() : subscriptions;
}
/**
 * Normalize the channel's `deploySourceUris` option into concrete
 * subscriptions. An omitted or empty option resolves to none, which callers
 * read as "defer to the deploy scope".
 */
export function resolveDeploymentSubscriptions(options) {
    const bySource = new Map();
    for (const entry of options.deploySourceUris ?? []) {
        const subscription = typeof entry === "string" ? { deploySourceUri: entry } : entry;
        // Case-folded only: `Deployment.deploy_source_uri` has no documented
        // format, and the server keys subscriptions the same way.
        const deploySourceUri = subscription.deploySourceUri.trim().toLowerCase();
        if (deploySourceUri === "") {
            throw new Error(`deploymentsChannel: invalid deploy source "${subscription.deploySourceUri}".`);
        }
        const environments = [
            ...new Set((subscription.environments ?? options.environments ?? [])
                .map((value) => value.trim())
                .filter(Boolean)),
        ];
        const events = new Set(subscription.events ?? options.events ?? DEFAULT_EVENTS);
        if (events.size === 0) {
            throw new Error(`deploymentsChannel: deploy source "${deploySourceUri}" subscribes to no events.`);
        }
        // Later entries for the same deploy source widen the earlier one rather
        // than silently replacing it.
        const existing = bySource.get(deploySourceUri);
        if (existing === undefined) {
            bySource.set(deploySourceUri, { deploySourceUri, environments, events });
            continue;
        }
        for (const event of events)
            existing.events.add(event);
        existing.environments =
            existing.environments.length === 0 || environments.length === 0
                ? []
                : [...new Set([...existing.environments, ...environments])];
    }
    // Empty means "this channel names nothing". The relay wire reads that as
    // deregistration, hosted admission reads it as "defer to the deploy
    // scope". The host re-resolves on each heartbeat, so a channel that later
    // fills `deploySourceUris` registers without a restart.
    return [...bySource.values()];
}
/**
 * Union per-channel subscriptions, widening events and environments when
 * the same deploy source appears more than once. An empty environment
 * list means every environment and absorbs a narrower list.
 */
export function mergeResolvedSubscriptions(groups) {
    const bySource = new Map();
    for (const group of groups) {
        for (const subscription of group) {
            const existing = bySource.get(subscription.deploySourceUri);
            if (existing === undefined) {
                bySource.set(subscription.deploySourceUri, {
                    deploySourceUri: subscription.deploySourceUri,
                    environments: [...subscription.environments],
                    events: new Set(subscription.events),
                });
                continue;
            }
            for (const event of subscription.events)
                existing.events.add(event);
            existing.environments =
                existing.environments.length === 0 || subscription.environments.length === 0
                    ? []
                    : [...new Set([...existing.environments, ...subscription.environments])];
        }
    }
    return [...bySource.values()];
}
/** Whether one confirmed subscription wants this event. */
export function deploymentEventMatches(subscription, envelope) {
    if (!subscription.events.has(envelope.eventType)) {
        return false;
    }
    return (subscription.environments.length === 0 ||
        subscription.environments.includes(envelope.environment));
}
/**
 * Deliver one event to every channel subscribed to it.
 *
 * Each channel is delivered independently: one channel's handler throwing
 * must not skip the channels after it, because the relay core retries the
 * whole dispatch and the channels that already ran would see the event twice.
 * Throws only when every subscribed channel failed, so a retry cannot
 * re-deliver to a channel that succeeded.
 */
export async function fanOutDeploymentEvent(input) {
    const { event, logger } = input;
    const matched = input.targets.filter((target) => target.subscriptions.some((subscription) => subscription.deploySourceUri === event.deploySourceUri &&
        deploymentEventMatches(subscription, event)));
    const failures = [];
    for (const target of matched) {
        try {
            await target.deliver(event);
        }
        catch (error) {
            failures.push(target.name);
            logger(`[bdk] deployment-events: ${target.name} failed on ${event.eventId}: ${error instanceof Error ? error.message : String(error)}`);
        }
    }
    logger(`[bdk] deployment-events: ${event.eventType} ${event.deploySourceUri}@${event.deployVersion} (${event.environment}) → ${matched.length - failures.length}/${matched.length} channel(s)`);
    if (failures.length > 0 && failures.length === matched.length) {
        throw new Error(`deployment-events: every subscribed channel failed on ${event.eventId} (${failures.join(", ")})`);
    }
}
export class DeploymentEventRelay {
    constructor(options) {
        this.options = options;
        this.subscribed = new Map();
        this.loggedSkippedSources = new Set();
        const adapter = {
            logPrefix: "deployment-events",
            subscribePath: "/v0/deployment-events/subscriptions",
            pollPath: "/v0/deployment-events",
            buildRegistrationBody: (consumerId) => ({
                consumerId,
                subscriptions: currentDeploymentSubscriptions(options.subscriptions).map((subscription) => ({
                    deploySourceUri: subscription.deploySourceUri,
                    environments: subscription.environments,
                    events: [...subscription.events],
                })),
            }),
            // Empty subscriptions drop this consumer's registration on clean stop
            // instead of leaving it to lapse by TTL.
            buildDeregistrationBody: (consumerId) => ({
                consumerId,
                subscriptions: [],
            }),
            applyRegistrationResponse: (json) => {
                const wantedSubscriptions = currentDeploymentSubscriptions(options.subscriptions);
                this.subscribed = new Map();
                this.loggedSkippedSources.clear();
                const lines = [];
                const confirmed = [];
                for (const status of deploymentSubscriptionStatuses(json)) {
                    const wanted = wantedSubscriptions.find((subscription) => subscription.deploySourceUri === status.deploySourceUri);
                    if (!status.isSubscribed || wanted === undefined) {
                        lines.push(`not subscribed to ${status.deploySourceUri}: ${status.detail ?? "unknown reason"}`);
                        continue;
                    }
                    this.subscribed.set(status.deploySourceUri, wanted);
                    confirmed.push(status.deploySourceUri);
                }
                if (confirmed.length > 0) {
                    const kinds = [...new Set(wantedSubscriptions.flatMap((s) => [...s.events]))];
                    lines.push(`subscribed to ${confirmed.join(", ")} for events: ${kinds.join(", ")}`);
                }
                return lines;
            },
            shouldDispatch: (event) => this.shouldDispatch(event),
            dispatch: ({ offset: _offset, ...envelope }) => options.dispatch(envelope),
        };
        this.core = new CursorRelayCore({
            baseUrl: options.baseUrl,
            apiKey: options.apiKey,
            stateDir: options.stateDir,
            adapter,
            logger: options.logger,
            ...(options.fetchImpl === undefined ? {} : { fetchImpl: options.fetchImpl }),
            ...(options.pollWaitMs === undefined ? {} : { pollWaitMs: options.pollWaitMs }),
        });
    }
    /**
     * Whether an event from this principal's stream belongs to THIS relay.
     * The stream is per-principal, and one API key can back several relays
     * (other hosts, or an agent running its own alongside the host's), so each
     * one re-checks the events against the subscriptions the server confirmed
     * for it.
     */
    shouldDispatch(event) {
        const envelope = event;
        if (envelope === null ||
            typeof envelope !== "object" ||
            typeof envelope.deploySourceUri !== "string") {
            return false;
        }
        const subscription = this.subscribed.get(envelope.deploySourceUri);
        if (subscription === undefined) {
            if (!this.loggedSkippedSources.has(envelope.deploySourceUri)) {
                this.loggedSkippedSources.add(envelope.deploySourceUri);
                this.options.logger(`[bdk] deployment-events: skipping events for ${envelope.deploySourceUri}: not in this host's subscription (another consumer of this API key likely subscribed it)`);
            }
            return false;
        }
        return deploymentEventMatches(subscription, envelope);
    }
    start() {
        this.core.start();
    }
    async stop() {
        await this.core.stop();
    }
}
